-- Controlled schema expansion: tenant indexes and session replay tracking.
ALTER TABLE sessions ADD COLUMN IF NOT EXISTS family_id uuid NOT NULL DEFAULT gen_random_uuid();
ALTER TABLE sessions ADD COLUMN IF NOT EXISTS rotated_at timestamptz;
ALTER TABLE sessions ADD COLUMN IF NOT EXISTS last_step_up_at timestamptz;
CREATE INDEX IF NOT EXISTS sessions_family_idx ON sessions(family_id);
CREATE TABLE IF NOT EXISTS invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),email text NOT NULL,role text NOT NULL CHECK(role IN ('admin','operator','developer','analyst','viewer')),token_hash text NOT NULL UNIQUE,invited_by uuid NOT NULL REFERENCES users(id),expires_at timestamptz NOT NULL,accepted_at timestamptz,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS invitations_org_idx ON invitations(organization_id);
CREATE TABLE IF NOT EXISTS datasets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL,description text NOT NULL DEFAULT '',artifact_id uuid REFERENCES artifacts(id),created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,UNIQUE(organization_id,name));
CREATE TABLE IF NOT EXISTS experiments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL,baseline_benchmark_id uuid NOT NULL REFERENCES benchmarks(id),candidate_benchmark_id uuid NOT NULL REFERENCES benchmarks(id),status text NOT NULL DEFAULT 'configured',comparison jsonb,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(baseline_benchmark_id<>candidate_benchmark_id));
CREATE TABLE IF NOT EXISTS routing_policies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL,model_id uuid NOT NULL REFERENCES models(id),enabled boolean NOT NULL DEFAULT true,concurrency_cap integer NOT NULL DEFAULT 1 CHECK(concurrency_cap>0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,model_id));
CREATE TABLE IF NOT EXISTS notification_preferences(organization_id uuid PRIMARY KEY REFERENCES organizations(id),email_enabled boolean NOT NULL DEFAULT true,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS alert_incidents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),title text NOT NULL,severity text NOT NULL CHECK(severity IN ('info','warning','critical')),source text NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now(),acknowledged_by uuid REFERENCES users(id),acknowledged_at timestamptz);
CREATE INDEX IF NOT EXISTS alerts_org_idx ON alert_incidents(organization_id,occurred_at DESC);
CREATE TABLE IF NOT EXISTS model_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),model_id uuid NOT NULL REFERENCES models(id),tag text NOT NULL,upstream_name text NOT NULL,sha256 text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(model_id,tag));
CREATE TABLE IF NOT EXISTS backup_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),status text NOT NULL CHECK(status IN ('running','completed','failed')),method text NOT NULL,size_bytes bigint,started_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,detail text);
